INSERT INTO db_config VALUES ('actividad.8.card_text_eu', 'Adinekoentzako tai chi mugimendu motel, fluido eta kontzienteetan oinarritutako diziplina terapeutikoa da, arnasketa sakon eta meditazioarekin batera, askotan "mugimendu meditazioa" deitzen dena. Ariketa seguru eta inpaktu txikikoa da, oreka, indarra, malgutasuna eta bizkortasun mentala hobetzen dituena, erortzeko arriskua murriztuz.
