INSERT INTO db_config VALUES ('actividad.8.card_text', 'El taichi para mayores es una disciplina terapéutica basada en movimientos lentos, fluidos y conscientes, acompañados de respiración profunda y meditación, a menudo llamada "meditación en movimiento". Es un ejercicio seguro de bajo impacto que mejora el equilibrio, la fuerza, la flexibilidad y la agilidad mental, reduciendo el riesgo de caídas. 
